LL fpow(LL x, LL a)
{
	LL ret = 1;
	while(a)
	{
		if(a & 1)
			ret = ret * x % mod;
		a >>= 1;
		x = x * x % mod;
	}
	return ret;
}
LL ni(LL x)
{
	return fpow(x, mod - 2);
}

