LL mod;

LL pot(LL a, LL w)
{
  if(w == 0)
    return 1;
  LL b = pot(a, w / 2);
  b = (b * b) % mod;
  if(w & 1)
    b = (b * a) % mod;
  return b;
}

LL odw(LL a)
{
  return pot(a, mod - 2);
}

LL po2(LL a)
{
  return ((a * (a - 1)) / 2LL);
}

LL dp[maxn];

LL licz(LL a, LL b)
{
  if(a > b)
    swap(a, b);
  LL cnt = 0LL;
  for(int i = 0 ;i <= a + b;i++)
    dp[i] = 0;
  for(int i = 1;i <= b;i++)
  {
    dp[i + 1]++;
    dp[i + a + 1]--;
  }
  for(int i = 2;i <= a + b;i++)
  {
    dp[i] += dp[i - 1];
    cnt += dp[i] * (odw(2) - odw(i));
    cnt %= mod;
  }
  return cnt;
}

